import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { 
  ChevronLeft, ChevronRight, Plus, Trash2, Lock, Unlock, 
  Palette, KeyRound, Bookmark, Sparkles 
} from 'lucide-react';
import { useWorkspaceStore } from '../../store/useWorkspaceStore';

export default function Notebook() {
  const { 
    notebook, 
    setNotebookCover, 
    setNotebookPin, 
    unlockNotebook, 
    lockNotebook, 
    nextPage, 
    prevPage, 
    addNewPage, 
    updateCurrentPage, 
    deleteCurrentPage 
  } = useWorkspaceStore();

  const [enteredPin, setEnteredPin] = useState('');
  const [pinError, setPinError] = useState(false);
  const [isPinModalOpen, setIsPinModalOpen] = useState(false);
  const [newPinInput, setNewPinInput] = useState('');
  const [isCoverModalOpen, setIsCoverModalOpen] = useState(false);

  const currentPageData = notebook.pages[notebook.currentPage] || { title: '', content: '', date: '' };

  // Cover styling themes
  const coverStyles = {
    'vintage-leather': {
      bg: 'bg-[#4a2810]',
      border: 'border-[#2f1707]',
      accent: 'border-[#d4af37]',
      name: 'Vintage Leather',
      spine: 'from-[#2e1608] via-[#4a2810] to-[#2e1608]'
    },
    'obsidian': {
      bg: 'bg-[#18181b]',
      border: 'border-[#09090b]',
      accent: 'border-zinc-500',
      name: 'Obsidian Noir',
      spine: 'from-[#000000] via-[#18181b] to-[#000000]'
    },
    'emerald-velvet': {
      bg: 'bg-[#143e2e]',
      border: 'border-[#0a2319]',
      accent: 'border-[#52b788]',
      name: 'Emerald Velvet',
      spine: 'from-[#081a13] via-[#143e2e] to-[#081a13]'
    },
    'royal-blue': {
      bg: 'bg-[#1e293b]',
      border: 'border-[#0f172a]',
      accent: 'border-[#38bdf8]',
      name: 'Royal Blue',
      spine: 'from-[#0b1120] via-[#1e293b] to-[#0b1120]'
    }
  };

  const currentTheme = coverStyles[notebook.cover] || coverStyles['vintage-leather'];

  const handleUnlock = (e) => {
    e.preventDefault();
    const success = unlockNotebook(enteredPin);
    if (success) {
      setPinError(false);
      setEnteredPin('');
    } else {
      setPinError(true);
    }
  };

  const handleSavePin = (e) => {
    e.preventDefault();
    setNotebookPin(newPinInput.trim());
    setIsPinModalOpen(false);
    setNewPinInput('');
  };

  return (
    <div className="relative w-full h-full flex flex-col items-center justify-between overflow-hidden bg-[#18100a] select-none p-2 sm:p-4 pb-20">
      
      {/* Top Glass Control Toolbar */}
      <div className="z-30 w-full max-w-xl bg-stone-900/90 backdrop-blur-md px-3 py-2 rounded-xl border border-amber-950/70 flex items-center justify-between gap-2 shadow-xl mb-3">
        <div className="flex items-center gap-2">
          {/* Cover Changer */}
          <button
            onClick={() => setIsCoverModalOpen(true)}
            className="flex items-center gap-1.5 bg-stone-800 hover:bg-stone-700 text-stone-200 px-2.5 py-1.5 rounded-lg text-xs font-semibold border border-stone-700 transition"
          >
            <Palette size={13} className="text-amber-400" />
            <span className="hidden sm:inline">Cover:</span> {currentTheme.name}
          </button>

          {/* PIN Lock Settings */}
          <button
            onClick={() => setIsPinModalOpen(true)}
            className="flex items-center gap-1.5 bg-stone-800 hover:bg-stone-700 text-stone-200 px-2.5 py-1.5 rounded-lg text-xs font-semibold border border-stone-700 transition"
          >
            <KeyRound size={13} className="text-amber-400" />
            <span>{notebook.hasPin ? 'Change PIN' : 'Set PIN'}</span>
          </button>
        </div>

        {/* Lock/Unlock Quick Status */}
        {notebook.hasPin && (
          <button
            onClick={notebook.isLocked ? undefined : lockNotebook}
            className={`flex items-center gap-1 px-2.5 py-1 rounded-lg text-xs font-bold transition shadow ${
              notebook.isLocked 
                ? 'bg-rose-500/20 text-rose-300 border border-rose-500/30 cursor-default' 
                : 'bg-emerald-600/20 hover:bg-emerald-600/30 text-emerald-300 border border-emerald-500/30'
            }`}
          >
            {notebook.isLocked ? <Lock size={12} /> : <Unlock size={12} />}
            <span>{notebook.isLocked ? 'Locked' : 'Lock Book'}</span>
          </button>
        )}
      </div>

      {/* 3D Realistic Open Notebook Container */}
      <div className="relative w-full max-w-xl flex-1 flex items-center justify-center">
        
        {/* Outer Hardcover with Realistic Bevel and Drop Shadows */}
        <div className={`relative w-full h-[75vh] max-h-[580px] rounded-2xl ${currentTheme.bg} border-4 ${currentTheme.border} shadow-[0_20px_50px_rgba(0,0,0,0.85)] flex overflow-hidden p-2.5 sm:p-3.5 transition-colors duration-300`}>
          
          {/* Gold Decorative Corner Stamp */}
          <div className="absolute top-2 left-2 w-3 h-3 border-t-2 border-l-2 border-amber-400/50" />
          <div className="absolute top-2 right-2 w-3 h-3 border-t-2 border-r-2 border-amber-400/50" />
          <div className="absolute bottom-2 left-2 w-3 h-3 border-b-2 border-l-2 border-amber-400/50" />
          <div className="absolute bottom-2 right-2 w-3 h-3 border-b-2 border-r-2 border-amber-400/50" />

          {/* Book Spine Center Shadow Effect */}
          <div className={`absolute top-0 bottom-0 left-6 sm:left-8 w-6 bg-gradient-to-r ${currentTheme.spine} opacity-70 z-20 pointer-events-none shadow-inner`} />

          {/* Realistic Paper Sheet */}
          <div 
            className="relative flex-1 w-full h-full rounded-r-xl rounded-l-md ml-4 sm:ml-6 flex flex-col justify-between p-4 sm:p-6 shadow-[inset_15px_0_20px_rgba(0,0,0,0.15),-2px_0_5px_rgba(0,0,0,0.1)] overflow-hidden"
            style={{
              backgroundColor: '#fbf7ee',
              backgroundImage: 'linear-gradient(rgba(180, 160, 140, 0.18) 1px, transparent 1px)',
              backgroundSize: '100% 28px'
            }}
          >
            {/* PIN Locked Blur View */}
            {notebook.isLocked ? (
              <div className="absolute inset-0 bg-[#fbf7ee]/70 backdrop-blur-md z-30 flex flex-col items-center justify-center p-6 text-center">
                <div className="w-12 h-12 rounded-full bg-amber-500/20 border border-amber-500/40 flex items-center justify-center text-amber-900 mb-3 shadow">
                  <Lock size={24} />
                </div>
                <h3 className="text-base font-extrabold text-stone-900">This Diary is Protected</h3>
                <p className="text-xs text-stone-600 mt-1 mb-4">Enter your 4-digit PIN to open pages</p>

                <form onSubmit={handleUnlock} className="flex flex-col items-center gap-2.5">
                  <input
                    type="password"
                    maxLength={4}
                    placeholder="••••"
                    value={enteredPin}
                    onChange={(e) => setEnteredPin(e.target.value)}
                    className="w-32 tracking-[0.5em] text-center text-lg font-black py-2 px-3 bg-white/90 border border-stone-400 rounded-xl outline-none focus:border-amber-600 text-stone-900 shadow-inner"
                  />
                  {pinError && <span className="text-[11px] text-rose-600 font-bold">Wrong PIN, try again!</span>}
                  <button
                    type="submit"
                    className="mt-1 bg-stone-900 hover:bg-stone-800 text-amber-300 px-5 py-2 rounded-xl text-xs font-bold transition shadow active:scale-95"
                  >
                    Unlock Diary
                  </button>
                </form>
              </div>
            ) : null}

            {/* Page Header: Bookmark, Date, & Delete */}
            <div className="flex items-center justify-between border-b border-amber-900/10 pb-2">
              <div className="flex items-center gap-2">
                <Bookmark size={16} className="text-rose-600 fill-rose-600 -mt-1" />
                <span className="text-[11px] font-bold text-stone-500 uppercase tracking-wider">
                  {currentPageData.date || 'Today'}
                </span>
              </div>

              <div className="flex items-center gap-2">
                <span className="text-[11px] font-black text-stone-400 bg-stone-900/5 px-2 py-0.5 rounded">
                  Page {notebook.currentPage + 1} of {notebook.pages.length}
                </span>

                {notebook.pages.length > 1 && (
                  <button
                    onClick={deleteCurrentPage}
                    title="Delete this page"
                    className="p-1 rounded text-stone-400 hover:text-rose-600 hover:bg-stone-900/5 transition"
                  >
                    <Trash2 size={13} />
                  </button>
                )}
              </div>
            </div>

            {/* Page Title & Writing Area */}
            <div className="flex-1 flex flex-col mt-2">
              <input
                type="text"
                placeholder="Page Title / Heading..."
                value={currentPageData.title}
                onChange={(e) => updateCurrentPage(e.target.value, currentPageData.content)}
                className="w-full text-base sm:text-lg font-black text-stone-900 bg-transparent outline-none placeholder-stone-400 mb-2 border-b border-stone-300/40 pb-1"
              />

              <textarea
                placeholder="Start writing your thoughts, notes or reflections here..."
                value={currentPageData.content}
                onChange={(e) => updateCurrentPage(currentPageData.title, e.target.value)}
                className="w-full flex-1 bg-transparent text-xs sm:text-sm leading-[28px] text-stone-800 font-medium outline-none resize-none placeholder-stone-400"
              />
            </div>

            {/* Page Turning Navigation Footer */}
            <div className="flex items-center justify-between pt-2 border-t border-amber-900/10">
              <button
                onClick={prevPage}
                disabled={notebook.currentPage === 0}
                className="flex items-center gap-1 text-xs font-bold text-stone-600 disabled:opacity-30 hover:text-stone-900 transition"
              >
                <ChevronLeft size={16} /> Prev
              </button>

              <button
                onClick={addNewPage}
                className="flex items-center gap-1 bg-stone-900/10 hover:bg-stone-900/20 text-stone-900 px-3 py-1 rounded-lg text-xs font-bold transition active:scale-95"
              >
                <Plus size={13} /> New Page
              </button>

              <button
                onClick={nextPage}
                disabled={notebook.currentPage >= notebook.pages.length - 1}
                className="flex items-center gap-1 text-xs font-bold text-stone-600 disabled:opacity-30 hover:text-stone-900 transition"
              >
                Next <ChevronRight size={16} />
              </button>
            </div>

          </div>
        </div>
      </div>

      {/* POPUP MODAL: Change Cover */}
      <AnimatePresence>
        {isCoverModalOpen && (
          <div className="fixed inset-0 z-50 flex items-center justify-center p-3 bg-black/75 backdrop-blur-sm">
            <motion.div
              initial={{ scale: 0.9, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              exit={{ scale: 0.9, opacity: 0 }}
              className="w-full max-w-xs bg-stone-900 border border-amber-900/60 rounded-2xl p-4 shadow-2xl text-stone-200"
            >
              <h3 className="text-xs font-black text-amber-400 uppercase tracking-wider mb-3">
                Choose Diary Cover
              </h3>
              <div className="grid grid-cols-2 gap-2.5">
                {Object.entries(coverStyles).map(([key, item]) => (
                  <button
                    key={key}
                    onClick={() => {
                      setNotebookCover(key);
                      setIsCoverModalOpen(false);
                    }}
                    className={`p-3 rounded-xl border flex flex-col items-center gap-2 transition ${item.bg} ${
                      notebook.cover === key ? 'ring-2 ring-amber-400 scale-102' : 'border-stone-700 opacity-80 hover:opacity-100'
                    }`}
                  >
                    <span className="text-[11px] font-bold text-stone-100">{item.name}</span>
                  </button>
                ))}
              </div>
              <button
                onClick={() => setIsCoverModalOpen(false)}
                className="w-full mt-3 py-1.5 text-xs font-semibold bg-stone-800 hover:bg-stone-700 rounded-lg text-stone-300 transition"
              >
                Close
              </button>
            </motion.div>
          </div>
        )}
      </AnimatePresence>

      {/* POPUP MODAL: PIN Configuration */}
      <AnimatePresence>
        {isPinModalOpen && (
          <div className="fixed inset-0 z-50 flex items-center justify-center p-3 bg-black/75 backdrop-blur-sm">
            <motion.div
              initial={{ scale: 0.9, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              exit={{ scale: 0.9, opacity: 0 }}
              className="w-full max-w-xs bg-stone-900 border border-amber-900/60 rounded-2xl p-4 shadow-2xl text-stone-200"
            >
              <h3 className="text-xs font-black text-amber-400 uppercase tracking-wider mb-2">
                {notebook.hasPin ? 'Update PIN Protection' : 'Set 4-Digit PIN'}
              </h3>
              <p className="text-[11px] text-stone-400 mb-3">
                PIN set karne par diary tab open karne par PIN verify karna hoga. Khali chhod kar save karne par PIN remove ho jayega.
              </p>

              <form onSubmit={handleSavePin} className="space-y-3">
                <input
                  type="password"
                  maxLength={4}
                  placeholder="Enter 4-digit PIN"
                  value={newPinInput}
                  onChange={(e) => setNewPinInput(e.target.value)}
                  className="w-full px-3 py-2 bg-stone-950 border border-stone-700 rounded-xl text-center text-sm tracking-[0.4em] font-bold outline-none focus:border-amber-400 text-stone-100"
                />

                <div className="flex gap-2">
                  <button
                    type="button"
                    onClick={() => setIsPinModalOpen(false)}
                    className="flex-1 py-1.5 text-xs font-semibold bg-stone-800 hover:bg-stone-700 rounded-lg text-stone-300 transition"
                  >
                    Cancel
                  </button>
                  <button
                    type="submit"
                    className="flex-1 py-1.5 text-xs font-bold bg-amber-500 hover:bg-amber-400 text-stone-950 rounded-lg transition shadow"
                  >
                    Save PIN
                  </button>
                </div>
              </form>
            </motion.div>
          </div>
        )}
      </AnimatePresence>

    </div>
  );
}
